-- Sinh tự động từ spec, run_id 51fab4a1-fe03-4df1-b395-2d641f165a24. Không sửa tay.
-- domain: sales | độ hạt: event_date, channel
{{
    config(
        materialized='incremental',
        unique_key=['event_date', 'channel'],
        incremental_strategy='delete+insert',
    )
}}

with source_rows as (
    select channel, event_date, event_id, session_id
    from {{ source('bronze', 'raw_web_events') }}
    where true
    {% if is_incremental() %}
      and event_date >= (select coalesce(max(event_date), date '1900-01-01') from {{ this }})
    {% endif %}
)

select
    event_date,
    channel,
    COUNT(event_id) as events,
    COUNT(DISTINCT session_id) as sessions
from source_rows
group by event_date, channel
